def dfs(startnode, color):
  stack = []
  stack.append(startnode)
  startnode.visited = True
  startnode.cv = color
  while stack:
    actualnode = stack.pop()
    for neighbour in actualnode.adjacencyList:
      if not neighbour.visited:
        neighbour.visited = True
        neighbour.cv = color
        stack.append(neighbour)
class Node:
  def __init__(self,name):
    self.name = name
    self.cv = 0
    self.adjacencyList = []
    self.visited = False
n = int(input())
nodes = []
for i in range(1,n+1):
  nodes.append(Node(i))
start = 2
edges = list(map(int,input().split()))
for e in edges:
  nodes[e-1].adjacencyList.append(nodes[start-1])
  start += 1
colors = list(map(int,input().split()))
counter = 0
for i,color in enumerate(colors):
  if nodes[i].cv != color:
    counter += 1
    dfs(nodes[i], color)
    for node in nodes:
      node.visited = False
print(counter)

